"""Experiment adapter: map a request batch onto scheduler runs."""
from scheduler import Engine


def run_request(request):
    """Return the response object for one complete request document."""
    runs = request["runs"]
    out = []
    for cfg in runs:
        engine = Engine(cfg)
        log = engine.run(cfg["events"])
        out.append({"log": log, "state": engine.certificate()})
    return {"runs": out}
